#include "sqpcheader.h"
#include "sqvm.h"
#include "sqfuncproto.h"
#include "sqclosure.h"
#include "jit/sqjit_context.h"
#include "jit/sqjit_diagnostics.h"
#include <sqstdmath.h>
#include <sqstdstring.h>
#include <sqstdaux.h>
#include <fstream>
#include <sstream>
#include <cstdio>
#include <cstdlib>
#include <cstdarg>
static void output(HSQUIRRELVM, const SQChar *fmt, ...) {
    va_list args; va_start(args,fmt); vfprintf(stderr,fmt,args); va_end(args);
}
int main(int argc,char **argv) {
    if(argc!=4) return 2;
    std::ifstream file(argv[1]); std::ostringstream input; input<<file.rdbuf();
    std::string source=input.str();
    size_t marker=source.find("// The observer loads");
    if(marker!=std::string::npos) source.resize(marker);
    SQVM *v=sq_open(1024); sq_setprintfunc(v,output,output); sqstd_seterrorhandlers(v);
    sq_pushroottable(v); sqstd_register_mathlib(v); sqstd_register_stringlib(v); sq_pop(v,1);
    SQJitContext &ctx=sqjit_context(v->_sharedstate); ctx.threshold=1; ctx.collect_stats=true;
    bool ok=SQ_SUCCEEDED(sq_compilebuffer(v,source.c_str(),source.size(),argv[1],SQTrue));
    if(ok) { sq_pushroottable(v); ok=SQ_SUCCEEDED(sq_call(v,1,SQFalse,SQTrue)); }
    sq_settop(v,0);
    if(ok) {
        sq_pushroottable(v); sq_pushstring(v,argv[2],-1); ok=SQ_SUCCEEDED(sq_get(v,-2));
        if(ok) {
            sq_pushroottable(v); sq_pushinteger(v,atoll(argv[3]));
            ok=SQ_SUCCEEDED(sq_call(v,2,SQTrue,SQTrue));
            if(ok) { SQFloat result; sq_getfloat(v,-1,&result); printf("RESULT\t%.17g\n",(double)result); }
        }
    }
    SQJitDiagnostics &d=ctx.Diagnostics();
    puts("PROTO\tname\tenters\tcompile_ok\tcompile_fail\tframe_ok\tframe_guard\tdirect_ok\tdirect_guard\treject_ip\treason");
    for(SQInteger i=0;i<d.proto_count;++i) {
        const SQJitDiagProtoStats &p=d.protos[i];
        printf("PROTO\t%s\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\t%s\n",p.name,p.enters,p.compile_successes,p.compile_failures,p.exec_successes,p.exec_guard_failures,p.direct_successes,p.direct_guard_failures,p.last_reject_ip,p.last_reject_reason?p.last_reject_reason:"");
    }
    puts("LOOP\tname\theader\tattempts\tcompile_ok\tcompile_fail\texec_ok\tguard_fail");
    for(SQInteger i=0;i<d.loop_count;++i) {
        const SQJitDiagLoopStats &l=d.loops[i];
        printf("LOOP\t%s\t%lld\t%lld\t%lld\t%lld\t%lld\t%lld\n",l.name,l.header_ip,l.try_attempts,l.compile_successes,l.compile_failures,l.exec_successes,l.exec_guard_failures);
    }
    sq_close(v); return ok?0:1;
}

